use std::fs;
use std::path::Path;

// Ensure the embedded assets exist (possibly as placeholders) so that
// include_bytes! in src/dumper.rs compiles on fresh checkouts that have not
// run tools/embed-dumper.sh. Real assets are generated by that script.
fn main() {
    let assets = Path::new("assets");
    fs::create_dir_all(assets).expect("cannot create apiimo-api/assets");
    let bundle = assets.join("il2cpp-dumper.sfx.zst");
    if !bundle.exists() {
        fs::write(&bundle, []).expect("cannot write bundle placeholder");
    }
    let config = assets.join("config.json");
    if !config.exists() {
        fs::write(&config, b"{}").expect("cannot write config placeholder");
    }
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=assets/");
}
